from fastapi import APIRouter, HTTPException
from pydantic import BaseModel
from uuid import uuid4

router = APIRouter()
store: dict[str, dict] = {}

class {{model_name}}(BaseModel):
    name: str

@router.get('/{{resource}}')
def list_items():
    return list(store.values())

@router.post('/{{resource}}', status_code=201)
def create(item: {{model_name}}):
    iid = str(uuid4())
    obj = {'id': iid, **item.model_dump()}
    store[iid] = obj
    return obj

@router.get('/{{resource}}/{iid}')
def get_one(iid: str):
    if iid not in store: raise HTTPException(404)
    return store[iid]

@router.put('/{{resource}}/{iid}')
def update(iid: str, item: {{model_name}}):
    if iid not in store: raise HTTPException(404)
    store[iid].update(item.model_dump())
    return store[iid]

@router.delete('/{{resource}}/{iid}', status_code=204)
def delete(iid: str):
    store.pop(iid, None)
